// Config — настройки. Меняйте значения справа от двоеточия.
return [{ json: {
  "timezone": "Europe/Kyiv",
  "locale": "ru-RU",
  "sheets_api_base": "https://sheets.googleapis.com/v4",
  "spreadsheet_id": "REPLACE_WITH_SPREADSHEET_ID",
  "contacts_sheet": "Contacts",
  "graph_api_base": "https://graph.facebook.com/v25.0",
  "phone_number_id": "REPLACE_WITH_PHONE_NUMBER_ID",
  "team_chat_id": "REPLACE_WITH_TEAM_CHAT_ID",
  "followup": {
    "enabled": true,
    "after_hours": 20,
    "text": "{name}, подскажите, вопрос ещё актуален? Если удобно, продолжим здесь."
  },
  "working_hours": {
    "mon": {
      "open": "09:00",
      "close": "19:00"
    },
    "tue": {
      "open": "09:00",
      "close": "19:00"
    },
    "wed": {
      "open": "09:00",
      "close": "19:00"
    },
    "thu": {
      "open": "09:00",
      "close": "19:00"
    },
    "fri": {
      "open": "09:00",
      "close": "19:00"
    },
    "sat": {
      "open": "09:00",
      "close": "19:00"
    }
  }
} }];

// Find Silent — clients who stopped answering mid-conversation. One gentle follow-up, while WhatsApp still allows it.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
// Contacts sheet: one row per WhatsApp number. The sheet may start empty: the header is written with the first contact.
const CCOLS = ['wa_id', 'name', 'phone', 'first_seen', 'last_in_at', 'last_out_at', 'status', 'stage', 'need', 'budget', 'timeline', 'details',
  'hot', 'handoff_until', 'followup_sent', 'history', 'manager', 'notes'];
const colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const CLAST = colLetter(CCOLS.length - 1);
const contactsRange = () => `${quoteSheet(cfg.contacts_sheet)}!A1:${CLAST}`;
const contactRow = (row) => `${quoteSheet(cfg.contacts_sheet)}!A${row}:${CLAST}${row}`;
const waBatchUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(contactsRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.catalog_sheet)}!A1:C`)}`;
const contactsTable = (values) => { const rows = values || []; const header = rows.length && rows[0][0] === 'wa_id'; return { header, rows: header ? rows.slice(1) : [] }; };
const ccell = (row, c) => row[CCOLS.indexOf(c)] || '';
const contactObject = (row) => Object.fromEntries(CCOLS.map((c) => [c, ccell(row, c)]));
const graphUrl = () => `${cfg.graph_api_base}/${encodeURIComponent(cfg.phone_number_id)}/messages`;
const waText = (to, body) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: false, body: String(body).slice(0, 4000) } });
const table = contactsTable($input.first().json.values);
const now = nowMs();
const here = localParts(now);
const day = (cfg.working_hours || {})[here.weekday];
const minutes = here.hour * 60 + here.minute;
const toMin = (t) => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };
const f = cfg.followup || {};
if (!f.enabled) return [{ json: { send: false, reason: 'disabled' } }];
if (!day || minutes < toMin(day.open) || minutes >= toMin(day.close)) return [{ json: { send: false, reason: 'outside_hours' } }];
const flagCol = colLetter(CCOLS.indexOf('followup_sent'));
const outCol = colLetter(CCOLS.indexOf('last_out_at'));
const items = [];
const updates = [];
table.rows.forEach((row, i) => {
  const c = contactObject(row);
  if (c.status !== 'bot' || !['new', 'qualifying'].includes(c.stage) || c.followup_sent === 'yes') return;
  const lastIn = Date.parse(c.last_in_at), lastOut = Date.parse(c.last_out_at);
  if (isNaN(lastIn) || isNaN(lastOut) || lastOut < lastIn) return; // the client wrote last: that is not silence
  const silent = (now - lastIn) / (60 * MIN);
  // 23.5 hours, not 24: the follow-up must arrive inside the 24-hour window.
  if (silent < (f.after_hours || 20) || silent > 23.5) return;
  const sheetRow = i + (table.header ? 2 : 1);
  items.push({ send: true, wa_id: c.wa_id, message: waText(c.wa_id, String(f.text || '').replace(/\{name\}/g, c.name || '').trim()), graph_url: graphUrl() });
  updates.push({ range: `${quoteSheet(cfg.contacts_sheet)}!${flagCol}${sheetRow}`, values: [['yes']] }, { range: `${quoteSheet(cfg.contacts_sheet)}!${outCol}${sheetRow}`, values: [[new Date(now).toISOString()]] });
});
if (!items.length) return [{ json: { send: false, reason: 'nobody' } }];
items[0].http = { method: 'POST', url: `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchUpdate`, body: { valueInputOption: 'RAW', data: updates } };
return items.map((json) => ({ json }));
